async function validateTransferFile(file){
 const allowed=new Set(["pdf","txt","csv","md","rtf","doc","docx","xls","xlsx","ppt","pptx","odt","ods","odp","json","xml","html","htm","css","js","ts","tsx","jsx","py","java","c","cpp","h","cs","php","sql","yaml","yml","toml","ini","log","sh","bat","ps1","rels","mimetype"]);
 const blocked=new Set(["jpg","jpeg","png","gif","webp","bmp","svg","heic","heif","avif","tif","tiff","mp4","mov","avi","mkv","webm","mpeg","mpg","3gp","mp3","wav","ogg","m4a","aac","flac","wma","amr","exe","msi","apk","aab","dmg","iso","dll","so","com","scr","jar","class","wasm","7z","rar","tar","gz","bz2","xz"]);
 const ext=(String(file.name||"").split(".").pop()||"").toLowerCase();
 if(blocked.has(ext))return "هذا النوع ممنوع: لا يُسمح بالصور أو الفيديو أو الصوت أو الملفات التنفيذية أو الأرشيفات غير المدعومة.";
 if(!allowed.has(ext)&&ext!=="zip")return "صيغة الملف غير مسموحة. اختر مستنداً أو ملفاً نصياً مدعوماً.";
 const head=new Uint8Array(await file.slice(0,16).arrayBuffer());
 const ascii=String.fromCharCode(...head);
 const mediaSignature=(head[0]===255&&head[1]===216&&head[2]===255)||(head[0]===137&&head[1]===80&&head[2]===78&&head[3]===71)||ascii.startsWith("GIF8")||ascii.startsWith("BM")||ascii.startsWith("II*\u0000")||ascii.startsWith("MM\u0000*")||(ascii.startsWith("RIFF")&&(ascii.slice(8,12)==="WEBP"||ascii.slice(8,12)==="WAVE"||ascii.slice(8,11)==="AVI"))||ascii.slice(4,8)==="ftyp"||ascii.startsWith("ID3")||ascii.startsWith("OggS")||ascii.startsWith("fLaC")||ascii.startsWith("\u001aE\u00df\u00a3")||(head[0]===255&&(head[1]&224)===224);
 if(mediaSignature)return "ممنوع إرسال الصور أو الصوت أو الفيديو حتى لو تم تغيير امتداد الملف.";
 const starts=(a)=>a.every((v,i)=>head[i]===v);
 if(ext==="pdf"&&!starts([37,80,68,70,45]))return "محتوى الملف لا يطابق صيغة PDF.";
 if(["doc","xls","ppt"].includes(ext)&&!starts([208,207,17,224,161,177,26,225]))return "محتوى المستند لا يطابق صيغته.";
 if(["docx","xlsx","pptx","odt","ods","odp","zip"].includes(ext)){
  if(!starts([80,75,3,4])&&!starts([80,75,5,6]))return "الأرشيف أو المستند المضغوط غير صالح.";
  const tailStart=Math.max(0,file.size-65557),tail=new Uint8Array(await file.slice(tailStart).arrayBuffer());
  let eocd=-1;for(let i=tail.length-22;i>=Math.max(0,tail.length-65557);i--){if(tail[i]===80&&tail[i+1]===75&&tail[i+2]===5&&tail[i+3]===6){eocd=i;break;}}
  if(eocd<0)return "تعذر التحقق من محتويات الملف المضغوط؛ تم رفضه.";
  const view=new DataView(tail.buffer,tail.byteOffset,tail.byteLength);
  const count=view.getUint16(eocd+10,true),cdSize=view.getUint32(eocd+12,true),cdOffset=view.getUint32(eocd+16,true);
  if(count===0xffff||cdSize===0xffffffff||cdOffset===0xffffffff||count>1000||cdOffset+cdSize>file.size)return "الأرشيف كبير التعقيد أو غير مدعوم وتم رفضه.";
  const cd=new Uint8Array(await file.slice(cdOffset,cdOffset+cdSize).arrayBuffer());let pos=0,seen=0;
  while(pos+46<=cd.length&&seen<count){
   if(cd[pos]!==80||cd[pos+1]!==75||cd[pos+2]!==1||cd[pos+3]!==2)return "بنية الأرشيف غير صالحة.";
   const flags=cd[pos+8]|(cd[pos+9]<<8),nl=cd[pos+28]|(cd[pos+29]<<8),xl=cd[pos+30]|(cd[pos+31]<<8),cl=cd[pos+32]|(cd[pos+33]<<8);
   if(flags&1)return "الأرشيف المحمي بكلمة مرور غير مدعوم للفحص الآمن حالياً.";
   const nameBytes=cd.slice(pos+46,pos+46+nl);let entry="";
   try{entry=new TextDecoder("utf-8",{fatal:true}).decode(nameBytes)}catch{return "اسم ملف داخل الأرشيف غير صالح.";}
   const base=entry.split("/").pop();if(base&&!entry.endsWith("/")){
    const inner=(base.split(".").pop()||"").toLowerCase();
    if(blocked.has(inner)||!allowed.has(inner))return "الأرشيف يحتوي على ملف غير مسموح ("+base+").";
    if(["docx","xlsx","pptx","odt","ods","odp","zip"].includes(inner))return "الأرشيفات المتداخلة أو المستندات المضغوطة داخل أرشيف غير مدعومة.";
   }
   pos+=46+nl+xl+cl;seen++;
  }
  if(seen!==count||pos>cd.length)return "تعذر التحقق الكامل من محتويات الأرشيف.";
 }
 if(["txt","csv","md","rtf","json","xml","html","htm","css","js","ts","tsx","jsx","py","java","c","cpp","h","cs","php","sql","yaml","yml","toml","ini","log","sh","bat","ps1"].includes(ext)){
  const sample=new Uint8Array(await file.slice(0,Math.min(file.size,65536)).arrayBuffer());
  if(sample.includes(0))return "الملف لا يبدو نصياً صالحاً.";
  try{new TextDecoder("utf-8",{fatal:true}).decode(sample)}catch{return "الملف النصي ليس بترميز UTF-8 صالح.";}
 }
 return null;
}

